mapper.select:
SELECT orders.*, users.username FROM orders
JOIN users ON orders.user_id = users.user_id
WHERE username = #{username} AND orders.order_status = 'PENDING';

mapper.insert:
INSERT INTO purchased_items (user_id, id, name, type) VALUES
(SELECT user_id FROM users WHERE username = ${username} LIMIT 1, #{item.id}, #{item.name}, #{item.type})
;
